import { CSSProperties } from '@src/shared/dom';
import { asObject } from '@src/shared/type-utils';
import { MenuItemBase, Value, CustomRenderFn } from '../ks-menu-item/types';
import { KsTooltip } from '../ks-tooltip';
import { SEARCH_MARK } from './constants';

export type SingleValueType = Value[];

enum ShowCheckedStrategyEnum {
  parent = 'parent',
  child = 'child',
  all = 'all',
}
export type ShowCheckedStrategy = `${ShowCheckedStrategyEnum}`;

export interface CascaderDataNode extends MenuItemBase<CascaderDataNode> {
  isLeaf?: boolean;
  children?: CascaderDataNode[];
  dataAttrs?: Record<`data-${string}`, string | boolean>;
}

export interface CascaderSearchNode extends MenuItemBase<CascaderDataNode> {
  highlight: [number, number] | null;
  label: CustomRenderFn<CascaderDataNode> | string;
  [SEARCH_MARK]?: CascaderDataNode[];
  children?: undefined;
}

export interface SearchConfig<OptionType extends CascaderDataNode = CascaderDataNode> {
  filter?: (inputValue: string, options: OptionType[]) => boolean;
  render?: (inputValue: string, path: OptionType[]) => unknown;
  sort?: (a: OptionType, b: OptionType, inputValue: string) => number;
  limit?: number | false;
  autoClearSearchValue?: boolean;
  /** search input placeholder */
  placeholder?: string;
}

export interface CascaderColumnSelectAllContext {
  index: number;
  options: CascaderDataNode[];
  prevValuePath: Value[];
}

export interface CascaderColumnSelectAllConfig {
  show?: boolean | ((context: CascaderColumnSelectAllContext) => boolean);
  label?: string;
}

export interface CascaderMultipleConfig {
  columnSelectAll?: boolean | CascaderColumnSelectAllConfig;
}

export type CascaderMultiple = boolean | CascaderMultipleConfig;

export const getMergedMultiple = (multiple: CascaderMultiple | undefined): boolean => Boolean(multiple);

export const getMultipleConfig = (multiple: CascaderMultiple | undefined): CascaderMultipleConfig =>
  asObject(multiple) || {};

export interface CascaderPartProps {
  tooltip?: Partial<KsTooltip>;
  popup?: { style?: CSSProperties } & Record<string, unknown>;
  columns?: CascaderColumnPartProps | CascaderColumnPartProps[];
}

export type CascaderColumnPartProps = {
  style?: CSSProperties;
} & Record<string, unknown>;
